function newContent(){const bundle=Object.fromEntries(textRegistry.map(x=>[x.key,{ru:x.ru,en:x.en}]));const landing={titleRu:'Осваивайте копирование в демо',titleEn:'Explore copying in demo',bodyRu:'Изучите каталог и проверьте настройки на учебных средствах.',bodyEn:'Explore the catalog and review settings with synthetic funds.',ctaRu:'Открыть каталог',ctaEn:'Open catalog',target:'/catalog',image:'preview'};const campaign={name:'Знакомство с каталогом',titleRu:'Изучите новый каталог',titleEn:'Explore the new catalog',bodyRu:'Посмотрите доступные учебные профили и условия копирования.',bodyEn:'Review available synthetic profiles and copying conditions.',audience:'both',placement:'inbox',start:'2026-10-13T12:30',end:'2026-10-20T12:30',purpose:'marketing'};return {tab:'texts',key:textRegistry[0].key,query:'',coverage:'all',surface:'all',editor:false,preview:false,previewLocale:'ru',previewWidth:'desktop',bundleVersion:12,bundle,versions:[{version:12,bundle:structuredClone(bundle),actor:'STAFF-201',comment:'Исходный учебный набор / Initial synthetic bundle'}],draft:null,raw:{},validated:null,previewed:null,landingVersion:1,landing,landingVersions:[{version:1,value:structuredClone(landing),actor:'STAFF-201'}],landingDraft:null,campaignVersion:2,campaign,state:'active',campaignVersions:[{version:1,value:{...campaign,titleRu:'Знакомство с каталогом',titleEn:'Meet the catalog'},actor:'STAFF-204'},{version:2,value:structuredClone(campaign),actor:'STAFF-201'}],campaignDraft:null,campaignEditor:false,audienceChecked:null,tested:null,facts:{candidates:124,excluded:24,eligible:100,late:2,queued:98,available:90,failed:4,unknown:4,displayed:60,read:38},clock:'2026-10-19T12:00',notifications:structuredClone(contentNotificationSeed),notification:null,nquery:'',nchannel:'all',nstatus:'all',nvenue:'all',nevent:'all',from:'2026-10-17',to:'2026-10-20',operation:null,history:[],outcome:'confirmed',technical:false,revoked:false,consentKnown:true,lateOptOut:true,serviceUnavailable:false,arabicDraft:false,error:null,notice:null};}
let content=newContent();
function contentAccess(){const role=state.role,owner=['ownerA','ownerB'].includes(role),marketing=role==='marketing',lead=role==='lead',read=owner||marketing||lead||role==='audit';return {read,edit:owner||marketing||lead,publish:(owner||marketing)&&!content.revoked,segment:owner||marketing,test:owner||marketing,pause:(owner||marketing)&&!content.revoked,notifications:owner||lead||role==='ops'||role==='audit',allNotifications:owner||role==='audit',locale:owner||marketing};}
function cn(ru,en){return pl(ru,en);}
function cb(ru,en,action,attrs='',cls='btn'){return `<button class="${cls}" data-content="${action}" ${attrs}>${cn(ru,en)}</button>`;}
