function cfield(id,ru,en,value,type='text',extra=''){return `<div class="field"><label for="${id}">${cn(ru,en)}</label><input id="${id}" name="${id}" type="${type}" value="${escape(value??'')}" ${extra}></div>`;}
function ctext(id,ru,en,value){return `<div class="field"><label for="${id}">${cn(ru,en)}</label><textarea id="${id}" name="${id}" rows="4">${escape(value??'')}</textarea></div>`;}
function cerror(ru,en){content.error=[ru,en];return false;}
function cnotice(ru,en){content.notice=[ru,en];return true;}
function cstatus(s){return cn(({active:'Показы включены',paused:'Показы приостановлены',scheduled:'Запланировано',blocked:'Запуск заблокирован',ended:'Период завершён',draft:'Черновик',pending:'Ожидается подтверждение',unknown:'Результат неизвестен',failed:'Подтверждённый отказ',conflict:'Конфликт версии',confirmed:'Подтверждено',available:'Доступно в приложении',delivered:'Доставка подтверждена',unconfigured:'Канал не подключён'})[s]||s,({active:'Showing',paused:'Paused',scheduled:'Scheduled',blocked:'Start blocked',ended:'Window ended',draft:'Draft',pending:'Awaiting confirmation',unknown:'Outcome unknown',failed:'Confirmed failure',conflict:'Version conflict',confirmed:'Confirmed',available:'Available in app',delivered:'Delivery confirmed',unconfigured:'Channel not connected'})[s]||s);}
function csignature(kind,draft){return JSON.stringify({kind,draft});}
function contentDraft(kind){return kind==='texts'?content.draft:kind==='landing'?content.landingDraft:content.campaignDraft;}
function contentVersion(kind){return kind==='texts'?content.bundleVersion:kind==='landing'?content.landingVersion:content.campaignVersion;}
function contentValidate(kind){const d=contentDraft(kind);if(!contentAccess().edit||!d)return false;if(d.base!==contentVersion(kind))return cerror('Действующая версия изменилась. Сравните и обновите черновик.','Active version changed. Compare and refresh your draft.');const check=(v,tokens,max)=>{if(!v||!v.trim()||v.length>max||/[<>]/.test(v)||/(javascript:|data:)/i.test(v))return false;const found=[...v.matchAll(/\{([^{}]+)\}/g)].map(x=>x[1]).sort();return JSON.stringify(found)===JSON.stringify([...tokens].sort());};if(kind==='texts'){for(const spec of textRegistry)for(const l of ['ru','en'])if(!check(d.bundle[spec.key]?.[l],spec.tokens,spec.max))return cerror('Проверьте оба перевода, переменные и предел учебного поля: 180 символов. HTML и произвольные ссылки не допускаются.','Check both translations, placeholders and the synthetic field limit: 180 characters. HTML and arbitrary links are not allowed.');for(const values of Object.values(d.bundle))if(Object.values(values).some(v=>/https?:\/\//i.test(v)))return cerror('Для этого учебного текста ссылки не разрешены.','Links are not allowed in this synthetic text.');}else{const v=d.value;const fields=kind==='landing'?['titleRu','titleEn','bodyRu','bodyEn','ctaRu','ctaEn']:['name','titleRu','titleEn','bodyRu','bodyEn'];if(fields.some(k=>!check(v[k],[],k.startsWith('body')?500:120)))return cerror('Заполните RU/EN. Учебные пределы: заголовок 120, текст 500 символов, без HTML и произвольных ссылок.','Complete RU/EN. Synthetic limits: title120, body500 characters, no HTML or arbitrary links.');if(fields.some(k=>/https?:\/\//i.test(v[k])))return cerror('Ссылка задаётся отдельной разрешённой целью.','Use a separately allowed link target.');if(kind==='landing'&&(!['/catalog','/help'].includes(v.target)||!['preview','none'].includes(v.image)))return cerror('Выберите разрешённую цель и иллюстрацию.','Choose an allowed target and illustration.');if(kind==='campaign'){if(!['both','Polymarket','Limitless'].includes(v.audience)||!['inbox','banner'].includes(v.placement)||v.purpose!=='marketing')return false;if(!v.start||!v.end||Number.isNaN(Date.parse(v.start))||Number.isNaN(Date.parse(v.end))||v.start>=v.end||v.end<=content.clock)return cerror('Период UTC должен быть корректным и завершаться после учебного текущего времени.','Use a valid UTC window ending after the synthetic current time.');}}if(!d.comment?.trim())return cerror('Добавьте причину изменения.','Add a change reason.');content.validated=csignature(kind,d);content.previewed=null;return cnotice('Проверка пройдена. Откройте предпросмотр точной версии.','Validation passed. Preview this exact version.');}
function contentSave(kind,values){if(!contentAccess().edit)return false;content.error=null;const comment=values.comment||'';if(kind==='texts'){const bundle=structuredClone(content.draft?.bundle||content.bundle);bundle[content.key]={ru:values.ru??'',en:values.en??''};content.draft={base:content.draft?.base??content.bundleVersion,bundle,comment,author:actor().id};}else{const keys=kind==='landing'?['titleRu','titleEn','bodyRu','bodyEn','ctaRu','ctaEn','target','image']:['name','titleRu','titleEn','bodyRu','bodyEn','audience','placement','start','end','purpose'];const value=Object.fromEntries(keys.map(k=>[k,values[k]??'']));if(kind==='campaign'&&(!contentAccess().segment)&&value.audience!==(content.campaignDraft?.value||content.campaign).audience)return cerror('Изменение аудитории требует отдельного права.','Changing the audience requires separate permission.');content[kind==='landing'?'landingDraft':'campaignDraft']={base:contentDraft(kind)?.base??contentVersion(kind),value,comment,author:actor().id};}content.validated=null;content.previewed=null;content.audienceChecked=null;content.tested=null;return cnotice('Черновик сохранён. Опубликованный вариант не изменился.','Draft saved. Published content is unchanged.');}
function contentSubmit(kind){const pause=kind==='pause';if(pause?!contentAccess().pause:!contentAccess().publish)return cerror('Нет права на это действие.','You do not have permission for this action.');if(content.serviceUnavailable)return cerror('Сервис недоступен. Черновик сохранён; публикация не отправлена.','Service unavailable. Draft retained; publication not submitted.');if(content.technical)return cerror('Технический режим запрещает продуктовую публикацию.','Technical mode blocks product publication.');if(content.operation&&['pending','unknown'].includes(content.operation.status))return cerror('Сначала проверьте ранее принятую операцию.','Check the accepted operation first.');const d=pause?{base:content.campaignVersion,value:content.campaign}:contentDraft(kind);if(!d)return false;if(pause&&!['active','scheduled'].includes(content.state))return false;if(!pause&&(content.validated!==csignature(kind,d)||content.previewed!==csignature(kind,d)||d.base!==contentVersion(kind)))return cerror('Проверьте и просмотрите текущий черновик заново.','Validate and preview the current draft again.');if(kind==='campaign'&&(content.tested!==csignature(kind,d)||content.audienceChecked!==csignature(kind,d)||!content.consentKnown||!content.lateOptOut))return cerror('Нужны проверка согласий, аудитории и тестовый просмотр этой версии.','Check consent, audience and test-preview this version.');content.operation={id:'PUB-DEMO-'+(content.history.length+1),kind,payload:structuredClone(d),actor:actor().id,status:'pending',applied:false};content.history.push(content.operation);contentResolve();return true;}
function contentResolve(){const op=content.operation;if(!op||!['pending','unknown'].includes(op.status))return false;if(content.serviceUnavailable)return cnotice('Сведения о прежней операции недоступны; её результат не изменён.','Existing operation evidence is unavailable; its outcome is unchanged.');op.status=content.outcome;if(['pending','unknown'].includes(op.status))return true;if(op.status==='conflict'){const kind=op.kind==='pause'?'campaign':op.kind,key=kind==='texts'?'bundleVersion':kind==='landing'?'landingVersion':'campaignVersion',list=kind==='texts'?content.versions:kind==='landing'?content.landingVersions:content.campaignVersions;content[key]++;list.push({version:content[key],actor:'STAFF-DEMO-CONCURRENT',comment:'Учебное конкурентное обновление / Synthetic concurrent update',...(kind==='texts'?{bundle:structuredClone(content.bundle)}:{value:structuredClone(kind==='landing'?content.landing:content.campaign)})});content.validated=null;return true;}if(op.status!=='confirmed'){content.validated=null;content.previewed=null;return true;}const kind=op.kind,d=op.payload;if(content.technical||(!contentAccess().publish&&kind!=='pause')||(kind==='pause'&&!contentAccess().pause)||d.base!==contentVersion(kind==='pause'?'campaign':kind)){op.status='conflict';content.validated=null;return false;}if(op.applied)return false;if(kind==='texts'){content.bundle=structuredClone(d.bundle);content.bundleVersion++;content.versions.push({version:content.bundleVersion,bundle:structuredClone(d.bundle),author:d.author,actor:op.actor,comment:d.comment});}else if(kind==='landing'){content.landing=structuredClone(d.value);content.landingVersion++;content.landingVersions.push({version:content.landingVersion,value:structuredClone(d.value),author:d.author,actor:op.actor,comment:d.comment});}else if(kind==='campaign'){if(!content.consentKnown||!content.lateOptOut){op.status='failed';return false;}content.campaign=structuredClone(d.value);content.campaignVersion++;content.state=d.value.start>content.clock?'scheduled':'active';content.facts=null;content.campaignVersions.push({version:content.campaignVersion,value:structuredClone(d.value),author:d.author,actor:op.actor,comment:d.comment});}else content.state='paused';op.applied=true;if(kind!=='pause'&&JSON.stringify(contentDraft(kind))===JSON.stringify(d)){content[kind==='texts'?'draft':kind==='landing'?'landingDraft':'campaignDraft']=null;content.validated=null;content.previewed=null;}return true;}
function contentOperation(){const op=content.operation;return op?`<section class="panel" aria-live="polite"><h3>${cn('Результат операции','Operation outcome')} ${op.id}</h3><p>${cstatus(op.status)} · ${op.actor}</p><p>${cn('Принятие не означает публикацию. До подтверждения показана последняя подтверждённая версия.','Accepted does not mean published. The last confirmed version remains active until confirmation.')}</p>${['pending','unknown'].includes(op.status)?cb('Проверить прежнюю операцию','Check existing operation','reconcile'):''}</section>`:'';}
function contentPage(){const a=contentAccess();if(!a.read&&!a.notifications)return heading(cn('Доступ недоступен','Access unavailable'))+'<p>'+cn('В этом назначении нет права на раздел. Вернитесь в разрешённое меню.','This assignment does not permit this section. Return to an allowed menu.')+'</p>';if(!a.read)content.tab='notifications';return `${heading(cn('Контент и маркетинг','Content and marketing'),cn('Тексты, публикации и связь с пользователями','Content, publications and user communication'))}<section class="content-workspace"><div class="tabs" role="tablist">${contentTabs.filter(([k])=>k==='notifications'?a.notifications:a.read).map(([k,ru,en])=>`<button class="${content.tab===k?'active':''}" role="tab" aria-selected="${content.tab===k}" data-content="tab" data-tab="${k}">${cn(ru,en)}</button>`).join('')}</div><p class="muted">${cn('Учебные тексты и агрегаты. Изменения не меняют тарифы и права; сообщения не отправляются.','Synthetic content and aggregates. Edits do not change tariffs or permissions; no messages are sent.')}</p>${content.error?`<p class="error" role="alert">${escape(cn(...content.error))}</p>`:''}${content.notice?`<p class="support-notice" role="status">${escape(cn(...content.notice))}</p>`:''}${content.serviceUnavailable?`<p class="support-notice">${cn('Сервис контента недоступен. Используется последняя подтверждённая версия, история не объявляется пустой.','Content service unavailable. The last confirmed version remains in use; history is not assumed empty.')}</p>`:''}${({texts:contentTexts,landing:contentLanding,campaigns:contentCampaigns,notifications:contentNotifications,history:contentHistory,languages:contentLanguages})[content.tab]()}${contentOperation()}${contentScenarios()}</section>`;}
function contentTexts(){if(content.editor)return contentTextEditor();const rows=textRegistry.filter(x=>(content.surface==='all'||x.key.startsWith(content.surface))&&[x.key,...Object.values(content.draft?.bundle[x.key]||content.bundle[x.key])].some(v=>v.toLowerCase().includes(content.query.toLowerCase()))&&(content.coverage!=='missing'||Object.values(content.draft?.bundle[x.key]||content.bundle[x.key]).some(v=>!v.trim())));return `<form id="content-filter-form" class="content-filters">${cfield('query','Поиск по ключу или тексту','Find key or text',content.query)}<div class="field"><label for="surface">${cn('Экран','Surface')}</label><select id="surface" name="surface">${options([['all',cn('Все экраны','All surfaces')],['catalog',cn('Каталог','Catalog')],['session',cn('Сессия','Session')],['funds',cn('Средства','Funds')]],content.surface)}</select></div><div class="field"><label for="coverage">${cn('Переводы','Translations')}</label><select id="coverage" name="coverage">${options([['all',cn('Все','All')],['missing',cn('Не заполнены','Missing')]],content.coverage)}</select></div><button class="btn">${cn('Применить','Apply')}</button>${cb('Сбросить','Reset','reset')}</form><h2>${cn('Набор текстов','Text bundle')} B-${content.bundleVersion}</h2>${dtable([cn('Ключ / назначение','Key / usage'),'RU','EN',cn('Состояние','State')],rows.map(x=>{const v=content.draft?.bundle[x.key]||content.bundle[x.key];return `<tr><td>${cb(x.key,x.key,'edit-text',`data-key="${x.key}"`,'user-link')}<small>${x.surface}</small></td><td>${escape(v.ru)}</td><td>${escape(v.en)}</td><td>${content.draft?cn('Есть черновик','Draft exists'):cn('Опубликовано','Published')}</td></tr>`;}))}${!rows.length?`<p>${cn('Нет подходящих текстов. Сбросьте фильтры.','No matching texts. Reset filters.')}</p>`:''}`;}
function contentTextEditor(){const spec=textRegistry.find(x=>x.key===content.key),v=content.raw['text:'+content.key]||{...(content.draft?.bundle[content.key]||content.bundle[content.key]),comment:content.draft?.comment||''};return `${cb('К списку текстов','Back to texts','text-back')}<h2>${spec.key}</h2><p>${spec.surface} · ${cn('Неизменяемый ключ. Обязательные переменные','Immutable key. Required placeholders')}: ${spec.tokens.length?spec.tokens.map(t=>'{'+t+'}').join(', '):cn('нет','none')}</p><form id="content-text-form"><fieldset class="content-edit-fields" ${!contentAccess().edit?'disabled':''}><div class="content-columns">${ctext('ru','Русский · RU','Russian · RU',v.ru)}${ctext('en','English · EN','English · EN',v.en)}</div>${cfield('comment','Причина изменения','Change reason',v.comment)}${contentAccess().edit?`<button class="btn" type="submit">${cn('Сохранить черновик','Save draft')}</button>`:''}</fieldset></form>${contentWorkflow('texts')}${content.preview?contentPreview('texts'):''}`;}
function contentBusy(){return content.operation&&['pending','unknown'].includes(content.operation.status);}
function contentComparison(kind,d){
 const active=kind==='texts'?content.bundle:kind==='landing'?content.landing:content.campaign, draft=d?.bundle||d?.value||{};
 const labels={titleRu:['Заголовок · RU','Title · RU'],titleEn:['Заголовок · EN','Title · EN'],bodyRu:['Текст · RU','Body · RU'],bodyEn:['Текст · EN','Body · EN'],ctaRu:['Кнопка · RU','Button · RU'],ctaEn:['Кнопка · EN','Button · EN'],target:['Переход кнопки','Button destination'],image:['Иллюстрация','Illustration'],name:['Название кампании','Campaign name'],audience:['Аудитория','Audience'],placement:['Размещение','Placement'],start:['Начало · UTC','Start · UTC'],end:['Окончание · UTC','End · UTC'],purpose:['Назначение','Purpose']};
 const rows=kind==='texts'?textRegistry.flatMap(spec=>['ru','en'].map(l=>[spec.surface+' · '+l.toUpperCase(),active[spec.key]?.[l],draft[spec.key]?.[l]])):Object.keys(active).map(k=>[labels[k]?cn(...labels[k]):k,active[k],draft[k]]);
 const value=v=>({preview:cn('Учебное изображение','Sample image'),none:cn('Нет','None'),both:cn('Обе площадки','Both venues'),inbox:cn('Входящие','Inbox'),banner:cn('Баннер','Banner'),marketing:cn('Маркетинг','Marketing'),'/catalog':cn('Каталог','Catalog'),'/help':cn('Помощь','Help')})[v]||String(v??'—');
 return `<section class="panel"><h3>${cn('Сравнение версий','Version comparison')}</h3><p>${cn('База черновика','Draft base')}: ${d.base} · ${cn('Действующая версия','Current version')}: ${contentVersion(kind)}</p><div class="content-comparison">${rows.map(([label,a,b])=>`<section class="content-comparison-row"><h4>${escape(label)}</h4><div><strong>${cn('Сейчас опубликовано','Currently published')}</strong><p>${escape(value(a))}</p></div><div><strong>${cn('Ваш черновик','Your draft')}${a!==b?' · '+cn('изменено','changed'):''}</strong><p>${escape(value(b))}</p></div></section>`).join('')}</div>${cb('Сохранить мой вариант на новой базе','Keep my version on the new base','rebase',`data-kind="${kind}"`)}</section>`;
}
function contentWorkflow(kind){const d=contentDraft(kind),a=contentAccess(),busy=contentBusy();return `${busy?`<p class="support-notice">${cn('Ранее принятая операция ещё не завершена. Проверьте её результат перед новой публикацией.','An accepted operation is unresolved. Check its result before publishing again.')}</p>`:''}<div class="content-actions">${busy?cb('Проверить прежнюю операцию','Check existing operation','reconcile','','btn primary'):''}${d&&a.edit?cb('Проверить черновик','Validate draft','validate',`data-kind="${kind}"`):''}${d?cb('Предпросмотр','Preview','preview',`data-kind="${kind}"`):''}${d&&a.publish&&!busy?cb('Опубликовать точную версию','Publish exact version','publish',`data-kind="${kind}"`,'btn primary'):''}${d&&d.base!==contentVersion(kind)&&a.edit?cb('Сравнить с актуальной версией','Compare with current version','compare-base',`data-kind="${kind}"`):''}</div>${d&&d.base!==contentVersion(kind)?`<p class="support-notice">${cn('Конфликт: ваш черновик сохранён. Обновление базовой версии требует новой проверки и предпросмотра.','Conflict: your draft is retained. Refreshing the base requires validation and preview again.')}</p>`:''}${content.baseComparison===kind&&d?contentComparison(kind,d):''}`;}

function contentPreview(kind){const d=contentDraft(kind);if(!d)return '';const en=content.previewLocale==='en',v=d.value;let body;if(kind==='texts'){const raw=d.bundle[content.key][content.previewLocale],vars={session:'S-DEMO-001',amount:'20.00',asset:'USDT',address:'0x1111111111111111111111111111111111111111'};body=`<p class="full-address">${escape(raw.replace(/\{([^{}]+)\}/g,(m,k)=>vars[k]||m))}</p>`;}else body=`<h2>${escape(en?v.titleEn:v.titleRu)}</h2><p>${escape(en?v.bodyEn:v.bodyRu)}</p>${kind==='landing'?`<button class="btn primary" type="button" data-content="preview-link">${escape(en?v.ctaEn:v.ctaRu)}</button><p>${escape(v.target)}</p>${v.image==='preview'?`<figure class="landing-figure"><strong>Shadow · Paper Alpha</strong><p>${cn('Демо-сессия · учебные средства','Demo session · synthetic funds')}</p><span>${cn('Комиссия 0%','Fee 0%')}</span></figure>`:''}`:''}`;return `<section class="panel"><div class="content-actions">${cb('RU','RU','preview-locale','data-locale="ru"')}${cb('EN','EN','preview-locale','data-locale="en"')}${cb('Мобильный вид','Mobile view','preview-width','data-width="mobile"')}${cb('Широкий вид','Wide view','preview-width','data-width="desktop"')}</div><p>${cn('Предпросмотр черновика. Не опубликовано.','Draft preview. Not published.')}</p><div class="content-preview ${content.previewWidth==='mobile'?'is-mobile':''}">${body}</div></section>`;}
function contentLanding(){const v=content.raw.landing||{...(content.landingDraft?.value||content.landing),comment:content.landingDraft?.comment||''};return `<h2>${cn('Разрешённые блоки лендинга','Allowed landing blocks')} · L-${content.landingVersion}</h2><p>${cn('Редактируются содержание и разрешённая цель кнопки. Свободный HTML и изменение сетки не предусмотрены.','Edit content and the allowed button target. Arbitrary HTML and grid changes are unavailable.')}</p><form id="content-landing-form"><fieldset class="content-edit-fields" ${!contentAccess().edit?'disabled':''}><div class="content-columns">${cfield('titleRu','Заголовок RU','Title RU',v.titleRu)}${cfield('titleEn','Заголовок EN','Title EN',v.titleEn)}${ctext('bodyRu','Описание RU','Description RU',v.bodyRu)}${ctext('bodyEn','Описание EN','Description EN',v.bodyEn)}${cfield('ctaRu','Кнопка RU','Button RU',v.ctaRu)}${cfield('ctaEn','Кнопка EN','Button EN',v.ctaEn)}<div class="field"><label for="target">${cn('Цель кнопки','Button target')}</label><select id="target" name="target">${options([['/catalog',cn('Каталог','Catalog')],['/help',cn('Помощь','Help')]],v.target)}</select></div><div class="field"><label for="image">${cn('Иллюстрация','Illustration')}</label><select id="image" name="image">${options([['preview',cn('Пример демо-сессии','Demo session preview')],['none',cn('Без иллюстрации','No illustration')]],v.image)}</select></div></div>${cfield('comment','Причина изменения','Change reason',v.comment)}${contentAccess().edit?`<button class="btn">${cn('Сохранить черновик','Save draft')}</button>`:''}</fieldset></form>${contentWorkflow('landing')}${content.preview?contentPreview('landing'):''}`;}
function contentCampaigns(){const a=contentAccess(),c=content.campaign,v=content.raw.campaign||{...(content.campaignDraft?.value||c),comment:content.campaignDraft?.comment||''};if(!content.campaignEditor)return `<h2>${cn('Объявления внутри приложения','In-app announcements')}</h2><p>${cn('Массовые email, Telegram и push не подключены. Учебное время','Bulk email, Telegram and push are not connected. Synthetic time')}: ${content.clock} UTC</p>${dtable([cn('Кампания','Campaign'),cn('Состояние','State'),cn('Размещение','Placement'),cn('Период UTC','UTC window')],[`<tr><td>${cb(c.name,c.name,'edit-campaign','','user-link')}<small>ANN-DEMO-01 · A-${content.campaignVersion}</small></td><td>${cstatus(content.state)}</td><td>${cn('Внутри приложения','In app')}</td><td>${escape(c.start)} — ${escape(c.end)}</td></tr>`])}<div class="content-actions">${a.edit?cb('Подготовить изменение','Prepare an edit','edit-campaign'):''}${a.pause&&!contentBusy()&&['active','scheduled'].includes(content.state)?cb('Приостановить будущие показы','Pause future displays','pause'):''}</div>${contentAudience()}${contentCampaignFacts()}`;return `${cb('К списку кампаний','Back to campaigns','campaign-back')}<h2>ANN-DEMO-01 · A-${content.campaignVersion}</h2><p>${cn('Черновик не показывается пользователям. Назначение: маркетинг; канал: внутри приложения.','Drafts are not shown to users. Purpose: marketing; channel: in app.')}</p><form id="content-campaign-form"><fieldset class="content-edit-fields" ${!contentAccess().edit?'disabled':''}>${cfield('name','Внутреннее название','Internal name',v.name)}<div class="content-columns">${cfield('titleRu','Заголовок RU','Title RU',v.titleRu)}${cfield('titleEn','Заголовок EN','Title EN',v.titleEn)}${ctext('bodyRu','Текст RU','Body RU',v.bodyRu)}${ctext('bodyEn','Текст EN','Body EN',v.bodyEn)}<div class="field"><label for="audience">${cn('Аудитория · агрегаты','Audience · aggregates')}</label><select id="audience" name="audience">${options([['both',cn('Обе площадки · RU/EN','Both venues · RU/EN')],['Polymarket','Polymarket · RU/EN'],['Limitless','Limitless · RU/EN']],v.audience)}</select></div><div class="field"><label for="placement">${cn('Размещение','Placement')}</label><select id="placement" name="placement">${options([['inbox',cn('Центр сообщений','Message center')],['banner',cn('Объявление в приложении','In-app announcement')]],v.placement)}</select></div>${cfield('start','Начало · UTC','Start · UTC',v.start,'datetime-local')}${cfield('end','Окончание · UTC','End · UTC',v.end,'datetime-local')}</div><input type="hidden" name="purpose" value="marketing">${cfield('comment','Причина изменения','Change reason',v.comment)}${a.edit?`<button class="btn">${cn('Сохранить черновик','Save draft')}</button>`:''}</fieldset></form>${contentWorkflow('campaign')}<div class="content-actions">${content.campaignDraft&&a.segment?cb('Проверить аудиторию и согласия','Check audience and consent','audience'):''}${content.campaignDraft&&a.test?cb('Тестовый просмотр без отправки','Test preview without sending','test'):''}</div>${contentAudience()}${content.preview?contentPreview('campaign'):''}`;}
function contentAudience(){if((content.campaignDraft?.value||content.campaign).audience!=='both')return `<section class="panel"><h3>${cn('Аудитория выбранной площадки','Selected venue audience')}</h3><p>${cn('Снимок не загружен. Число допущенных не подтверждено; запуск недоступен.','Snapshot not loaded. Eligible count is unconfirmed; launch is unavailable.')}</p></section>`;return `<section class="panel"><h3>${cn('Допуск аудитории','Audience eligibility')}</h3><p>${cn('Только агрегаты разрешённого учебного сегмента. Балансы, PnL, контакты и тексты обращений недоступны для отбора.','Only permitted synthetic segment aggregates. Balances, PnL, contacts and support messages are unavailable as filters.')}</p>${content.consentKnown?`<dl class="account-facts"><div><dt>${cn('Кандидаты','Candidates')}</dt><dd>124</dd></div><div><dt>${cn('Исключены','Excluded')}</dt><dd>24</dd></div><div><dt>${cn('Допущены в снимке','Eligible in snapshot')}</dt><dd>100</dd></div></dl><p>${cn('10 отказов · 6 неизвестных согласий · 5 ограничений частоты · 3 ограничения класса. Причины не пересекаются. Перед показом — повторная проверка; два поздних отказа уменьшают очередь до98.','10 opt-outs · 6 unknown consents · 5 frequency limits · 3 class restrictions. Reasons are disjoint. Eligibility is checked again before display; two late opt-outs reduce the queue to98.')}</p>`:`<p class="error">${cn('Правило согласия неизвестно. Запуск запрещён, размер доступной аудитории не подтверждён.','Consent rule unknown. Launch is blocked; eligible audience size is unconfirmed.')}</p>`}</section>`;}
function contentCampaignFacts(){const f=content.facts;return `<section class="panel"><h3>${cn('Факты показа текущей версии','Current-version display facts')}</h3>${f?`<div class="content-bars">${[['available','Доступно','Available',90],['displayed','Показ подтверждён','Display confirmed',60],['read','Прочтение подтверждено','Read confirmed',38]].map(([k,ru,en,n])=>`<div><span>${cn(ru,en)}</span><meter min="0" max="98" value="${f[k]}" aria-label="${cn(ru,en)}">${f[k]}</meter><strong>${f[k]}</strong></div>`).join('')}</div><p>${cn('Очередь98 = доступно90 + отказ4 + неизвестно4. Показ60 входит в доступно90, прочтение38 входит в показ60; эти показатели не складываются.','Queue98 = available90 + failed4 + unknown4. Display60 is within available90; read38 is within display60. Do not add these metrics.')}</p>`:`<p>${cn('Для этой версии подтверждающие события ещё не получены. Это не нулевые показы.','No confirming events received for this version yet. This does not mean zero displays.')}</p>`}</section>`;}
function contentNotificationRows(){const a=contentAccess();return content.notifications.filter(n=>(a.allNotifications||n.recipient===actor().id)&&(content.nquery===''||(n.id+' '+n.recipient).toLowerCase().includes(content.nquery.toLowerCase()))&&(content.nchannel==='all'||n.channel===content.nchannel)&&(content.nstatus==='all'||n.status===content.nstatus)&&(content.nvenue==='all'||n.venue===content.nvenue)&&(content.nevent==='all'||n.event===content.nevent)&&n.date>=content.from&&n.date<=content.to);}
function contentNotifications(){if(!contentAccess().notifications)return heading(cn('Доступ недоступен','Access unavailable'))+'<p>'+cn('В этом назначении нет права на раздел. Вернитесь в разрешённое меню.','This assignment does not permit this section. Return to an allowed menu.')+'</p>';const n=content.notifications.find(n=>n.id===content.notification);if(n){if(!contentAccess().allNotifications&&n.recipient!==actor().id)return heading(cn('Доступ недоступен','Access unavailable'))+'<p>'+cn('В этом назначении нет права на раздел. Вернитесь в разрешённое меню.','This assignment does not permit this section. Return to an allowed menu.')+'</p>';return `${cb('К журналу уведомлений','Back to notifications','notification-back')}<h2>${n.id}</h2><dl class="account-facts"><div><dt>${cn('Адресат','Recipient')}</dt><dd>${n.recipient}</dd></div><div><dt>${cn('Канал','Channel')}</dt><dd>${n.channel}</dd></div><div><dt>${cn('Состояние','State')}</dt><dd>${cstatus(n.status)}</dd></div><div><dt>${cn('Попытки','Attempts')}</dt><dd>${n.attempt}</dd></div><div><dt>${cn('Прочтение','Read')}</dt><dd>${n.read===null?cn('Нет данных','No evidence'):n.read?cn('Подтверждено адресатом','Confirmed by recipient'):cn('Не подтверждено','Unconfirmed')}</dd></div></dl><p>${escape(cn(n.ru,n.en))}</p><p>${cn('Создание записи не означает доставку; доставка не означает прочтение. Ознакомление не подтверждает деньги и не снимает ограничение.','Creation does not mean delivery; delivery does not mean read. Acknowledgement does not approve money or lift restrictions.')}</p><div class="content-actions">${n.recipient===actor().id&&n.status==='available'&&!n.read?cb('Я ознакомился','Mark as read by me','notification-read'):''}${n.status==='unknown'?cb('Проверить прежнюю попытку','Check existing attempt','notification-check'):''}${n.object?cb('Открыть связанный инцидент','Open linked incident','notification-object'):''}</div>`;}return `<h2>${cn('Операционные и защитные уведомления','Operational and security notifications')}</h2><p>${cn('Отдельный журнал событий. Из него нельзя создать маркетинговую рассылку.','A separate event log. It cannot create a marketing campaign.')}</p><form id="content-notification-filter" class="content-columns">${cfield('nquery','ID или адресат','ID or recipient',content.nquery)}${[['nchannel','Канал','Channel',[['all',cn('Все','All')],['app',cn('В приложении','In app')],['email','Email'],['telegram','Telegram']]],['nstatus','Состояние','State',[['all',cn('Все','All')],...['available','unknown','unconfigured','delivered','failed'].map(s=>[s,cstatus(s)])]],['nvenue','Площадка','Venue',[['all',cn('Все','All')],['Polymarket','Polymarket'],['Limitless','Limitless'],['none',cn('Без площадки','No venue')]]],['nevent','Событие','Event',[['all',cn('Все','All')],['incident',cn('Инцидент','Incident')],['security',cn('Защита','Security')],['support',cn('Поддержка','Support')]]]].map(([id,ru,en,values])=>`<div class="field"><label for="${id}">${cn(ru,en)}</label><select id="${id}" name="${id}">${options(values,content[id])}</select></div>`).join('')}${cfield('from','С · UTC','From · UTC',content.from,'date')}${cfield('to','По · UTC','To · UTC',content.to,'date')}<button class="btn">${cn('Применить','Apply')}</button>${cb('Сбросить','Reset','notification-reset')}</form>${dtable([cn('Запись','Record'),cn('Адресат','Recipient'),cn('Канал / площадка','Channel / venue'),cn('Состояние','State')],contentNotificationRows().map(n=>`<tr><td>${cb(n.id,n.id,'notification',`data-id="${n.id}"`,'user-link')}<small>${n.date} UTC</small></td><td>${n.recipient}</td><td>${n.channel} · ${n.venue==='none'?cn('Без площадки','No venue'):n.venue}</td><td>${cstatus(n.status)}</td></tr>`))}${!contentNotificationRows().length?`<p>${cn('В этой выборке нет записей.','No records in this selection.')}</p>`:''}`;}
function contentHistory(){return `<h2>${cn('Неизменяемые версии','Immutable versions')}</h2>${[['texts','Тексты','Texts',content.versions],['landing','Лендинг','Landing',content.landingVersions],['campaign','Кампания','Campaign',content.campaignVersions]].map(([kind,ru,en,list])=>`<section class="panel"><h3>${cn(ru,en)}</h3>${list.map(v=>`<p>${kind==='texts'?'B':kind==='landing'?'L':'A'}-${v.version} · ${cn('Автор черновика','Draft author')}: ${v.author||v.actor} · ${cn('Публикация','Publication')}: ${v.actor} ${contentAccess().publish&&v.version!==contentVersion(kind)?cb('Восстановить новым черновиком','Restore as new draft','restore',`data-kind="${kind}" data-version="${v.version}"`):''}</p>`).join('')}</section>`).join('')}<h3>${cn('Операции текущего сеанса','Current-session operations')}</h3>${content.history.map(op=>`<p>${op.id} · ${op.actor} · ${op.kind} · ${cstatus(op.status)}</p>`).join('')||`<p>${cn('Операций пока нет','No operations yet')}</p>`}`;}
function contentLanguages(){return `<h2>${cn('Языки продукта','Product languages')}</h2><p>${cn('Это набор переводов продукта, а не ваш личный язык интерфейса. Активный набор RU/EN публикуется целиком.','This is the product translation registry, not your personal interface language. The active RU/EN bundle is published together.')}</p>${dtable([cn('Язык','Language'),cn('Состояние','State'),cn('Резервный текст','Fallback')],[`<tr><td>Русский · ru</td><td>${cn('Активен','Active')}</td><td>${cn('Последний валидный набор → встроенный базовый текст','Last valid bundle → built-in baseline')}</td></tr>`,`<tr><td>English · en</td><td>${cn('Активен','Active')}</td><td>${cn('Последний валидный набор → встроенный базовый текст','Last valid bundle → built-in baseline')}</td></tr>`,...(content.arabicDraft?[`<tr><td>العربية · ar · RTL</td><td>${cn('Неактивный черновик · переводы не готовы','Inactive draft · translations incomplete')}</td><td>${cn('Не назначен','Not assigned')}</td></tr>`]:[])])}${contentAccess().locale&&!content.arabicDraft?cb('Добавить учебный неактивный язык','Add an inactive sample language','language-draft'):''}`;}
function contentScenarios(){return `<details class="account-test"><summary>${cn('Учебные состояния — не рабочие настройки','Synthetic states — not operational settings')}</summary><div class="field"><label for="content-outcome">${cn('Ответ публикации','Publication outcome')}</label><select id="content-outcome" data-content-outcome>${options(['confirmed','pending','unknown','failed','conflict'].map(s=>[s,cstatus(s)]),content.outcome)}</select></div>${[['technical','Технический режим','Technical mode'],['revoked','Право публикации отозвано','Publication permission revoked'],['consentKnown','Правило согласия известно','Consent rule known'],['lateOptOut','Повторная проверка поздних отказов доступна','Late opt-out recheck is available'],['serviceUnavailable','Сервис контента недоступен','Content service unavailable']].map(([key,ru,en])=>`<label><input type="checkbox" data-content-state="${key}" ${content[key]?'checked':''}> ${cn(ru,en)}</label>`).join('')}${cb('Проверить запланированный старт','Check scheduled start','schedule-check')}${cb('Проверить окончание периода','Check window end','schedule-end')}</details>`;}
function contentAction(action,el={dataset:{}}){const ds=el.dataset||{},a=contentAccess();if(!a.read&&!a.notifications)return false;content.error=null;content.notice=null;if(action==='open'){content.tab=a.read?'texts':'notifications';navigate('content');}else if(action==='tab'){if(ds.tab!=='notifications'&&!a.read||ds.tab==='notifications'&&!a.notifications)return false;content.tab=ds.tab;content.preview=false;}else if(action==='reset'){content.query='';content.coverage='all';content.surface='all';}else if(action==='edit-text'){if(!a.read||!textRegistry.some(x=>x.key===ds.key))return false;content.key=ds.key;content.editor=true;content.preview=false;}else if(action==='text-back'){content.editor=false;content.preview=false;}else if(action==='edit-campaign'){if(!a.read)return false;content.campaignEditor=true;content.preview=false;}else if(action==='campaign-back'){content.campaignEditor=false;content.preview=false;}else if(action==='validate')return contentValidate(ds.kind);else if(action==='preview'){const d=contentDraft(ds.kind);if(!d||content.validated!==csignature(ds.kind,d))return cerror('Сначала проверьте сохранённый черновик.','Validate the saved draft first.');content.previewed=csignature(ds.kind,d);content.preview=true;}else if(action==='preview-locale')content.previewLocale=ds.locale;else if(action==='preview-width')content.previewWidth=ds.width;else if(action==='preview-link')return cnotice('Это проверка цели кнопки в макете; клиентский сайт не открывается.','This verifies the button target in the mockup; the client site is not opened.');else if(action==='publish')return contentSubmit(ds.kind);else if(action==='pause')return contentSubmit('pause');else if(action==='reconcile')return contentResolve();else if(action==='compare-base'){if(!a.edit)return false;content.baseComparison=ds.kind;}else if(action==='rebase'){if(!a.edit||content.baseComparison!==ds.kind)return false;contentDraft(ds.kind).base=contentVersion(ds.kind);content.validated=null;content.previewed=null;content.baseComparison=null;}else if(action==='audience'){if(!a.segment||!content.campaignDraft||!content.consentKnown)return cerror('Нет подтверждённого правила согласия или права сегментирования.','Consent rule or segmentation permission is missing.');if(content.campaignDraft.value.audience!=='both')return cerror('Снимок выбранной площадки не загружен. Для учебного прохода выберите обе площадки.','Selected venue snapshot is unavailable. Choose both venues for this synthetic flow.');content.audienceChecked=csignature('campaign',content.campaignDraft);return cnotice('Снимок аудитории проверен. Перед показом согласие проверяется повторно.','Audience snapshot checked. Consent is checked again before display.');}else if(action==='test'){if(!a.test||content.validated!==csignature('campaign',content.campaignDraft)||content.audienceChecked!==csignature('campaign',content.campaignDraft))return cerror('Сначала проверьте содержание и аудиторию.','Validate content and audience first.');content.tested=csignature('campaign',content.campaignDraft);content.previewed=content.tested;content.preview=true;return cnotice('Тестовый просмотр готов. Сообщения не поставлены в очередь.','Test preview ready. No messages were queued.');}else if(action==='schedule-check'){if(content.state!=='scheduled')return false;content.clock=content.campaign.start;if(!a.publish||content.technical||!content.consentKnown||!content.lateOptOut||content.serviceUnavailable){content.state='blocked';return cerror('Запланированный старт заблокирован повторной проверкой. Автозапуска после снятия нет.','Scheduled start blocked by recheck. It will not resume automatically.');}content.state='active';content.facts=null;return cnotice('Учебный запуск подтверждён; факты показа ещё не получены.','Synthetic start confirmed; no display evidence received yet.');}else if(action==='schedule-end'){if(!['active','scheduled','paused','blocked'].includes(content.state))return false;content.clock=content.campaign.end;content.state='ended';return cnotice('Учебный период завершён. Новых показов нет; прежние факты сохранены.','Synthetic window ended. No new displays; previous facts retained.');}else if(action==='restore'){if(!a.publish)return false;const list=ds.kind==='texts'?content.versions:ds.kind==='landing'?content.landingVersions:content.campaignVersions,v=list.find(v=>v.version===Number(ds.version));if(!v)return false;const d={base:contentVersion(ds.kind),author:actor().id,comment:cn('Восстановление версии','Restore version')+' '+v.version,...(ds.kind==='texts'?{bundle:structuredClone(v.bundle)}:{value:structuredClone(v.value)})};content[ds.kind==='texts'?'draft':ds.kind==='landing'?'landingDraft':'campaignDraft']=d;content.raw={};content.validated=null;content.previewed=null;content.tested=null;content.audienceChecked=null;content.tab=ds.kind==='texts'?'texts':ds.kind==='landing'?'landing':'campaigns';content.editor=ds.kind==='texts';content.campaignEditor=ds.kind==='campaign';return cnotice('Создан новый черновик; опубликованная версия и история сохранены.','New draft created; published version and history are unchanged.');}else if(action==='language-draft'){if(!a.locale)return false;content.arabicDraft=true;}else if(action==='notification'){if(!contentNotificationRows().some(n=>n.id===ds.id))return false;content.notification=ds.id;}else if(action==='return-notification'){content.incidentReturn=false;navigate('content');}else if(action==='notification-back')content.notification=null;else if(action==='notification-reset'){Object.assign(content,{nquery:'',nchannel:'all',nstatus:'all',nvenue:'all',nevent:'all',from:'2026-10-17',to:'2026-10-20'});}else if(action.startsWith('notification-')){if(!a.notifications)return false;const n=content.notifications.find(n=>n.id===content.notification);if(!n||!a.allNotifications&&n.recipient!==actor().id)return false;if(action==='notification-read'){if(n.recipient!==actor().id||n.status!=='available')return false;n.read=true;}else if(action==='notification-check'){if(n.status!=='unknown')return false;return cnotice('Новых подтверждений не получено. Прежняя попытка остаётся неизвестной; повторной отправки нет.','No new evidence. The existing attempt remains unknown; nothing was resent.');}else if(action==='notification-object'){if(!n.object||!incidentAccess(state.role).read)return false;incidents.returnContext=false;incidents.returnTicket=false;const target=incidents.records.find(x=>x.id===n.object&&incidentAllowed(x));if(!target)return false;content.incidentReturn=true;incidentAction('open',{dataset:{id:n.object}});return true;}else return false;}else return false;return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-content]');if(!el||el.disabled)return;contentAction(el.dataset.content,el);render();});
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-content-outcome'))content.outcome=el.value;else if(el.dataset.contentState){content[el.dataset.contentState]=el.checked;if(['technical','revoked','consentKnown','lateOptOut'].includes(el.dataset.contentState)){content.audienceChecked=null;content.tested=null;}}else return;render();});
document.addEventListener('input',e=>{const form=e.target.closest('form');if(!form)return;const key=form.id==='content-text-form'?'text:'+content.key:form.id==='content-landing-form'?'landing':form.id==='content-campaign-form'?'campaign':null;if(key){content.raw[key]=Object.fromEntries(new FormData(form));content.validated=null;content.previewed=null;content.tested=null;}});
document.addEventListener('submit',e=>{const id=e.target.id;if(!id.startsWith('content-'))return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(id==='content-filter-form')Object.assign(content,{query:v.query||'',surface:v.surface,coverage:v.coverage});else if(id==='content-notification-filter'){if(!v.from||!v.to||v.from>v.to){cerror('Проверьте период UTC.','Check the UTC period.');render();return;}for(const k of ['nquery','nchannel','nstatus','nvenue','nevent','from','to'])content[k]=v[k];}else contentSave(id==='content-text-form'?'texts':id==='content-landing-form'?'landing':'campaign',v);render();});
